"""
并查集。将数组中每个数和他的因数进行链接的时候，要注意方法。（这个方法好像比质因数要快？）
时间复杂度:O(nlogn)
"""
import time
class DisjointunionSet:
    def __init__(self,n):
        self.parent=list(range(n))
        self.rank=[1]*n

    def find(self,x):
        if self.parent[x]==x:
            return x
        return self.find(self.parent[x])

    def Unionset(self,x,y):
        fx,fy=self.find(x),self.find(y)
        if fx==fy:
            return
        if self.rank[fx]<self.rank[fy]:
            fx,fy=fy,fx

        self.rank[fx]+=self.rank[fy]
        self.parent[fy]=fx


class Solution:
    def gcdSort(self,nums):
        maxnum=max(nums)

        n=len(nums)

        dsu=DisjointunionSet(maxnum+1)

        numset=set(nums)
        for i in range(2,maxnum+1):
            for j in range(i,maxnum+1,i):
                if j in numset:
                    dsu.Unionset(i,j)

        nums1=sorted(nums)

        for i in range(n):
            if nums1[i]==nums[i]:
                continue
            elif dsu.find(nums[i])!=dsu.find(nums1[i]):
                return False

        return True

